const T = 2; 
const RANGES = {
    s1: [0, 50],
    s2: [0, 100],
    s3: [0, 1]
};
const text = String(msg.payload).replace(/^\uFEFF/, ''); // Убираем BOM если есть
const sql = [];
text.split(/\r?\n/).forEach(raw => {
    const line = raw.trim();
    if (!line) return;
    const parts = line.split(' ');
    const kind = parts[0];
    const f = {};
    parts.slice(1).forEach(p => {
        const kv = p.split('=');
        if (kv.length === 2) {
            f[kv[0]] = kv[1];
        }
    });
    const n = parseInt(f.n);
    if (isNaN(n)) return;
    const t_s = n * T;
    if (kind === 'DATA') {
        ['s1', 's2', 's3'].forEach(s => {
            const v = parseFloat(f[s]);
            if (!isNaN(v)) {
                sql.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t_s},'${s}',${v});`);
            }
            const [min, max] = RANGES[s];
            if (isNaN(v) || v < min || v > max) {
                const safeMsg = `датчик ${s} вне диапазона [${min};${max}]`.replace(/'/g, "''");
                sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t_s},'FAULT','${safeMsg}');`);
            }
        });
    } 
    else if (kind === 'EVENT') {
        const type = f.type || 'UNKNOWN';
        let message = '';
        if (type === 'THRESHOLD') {
            message = 'влажность > 70%';
        } else if (type === 'NORMAL') {
            message = 'влажность в норме';
        } else {
            message = 'событие контроллера';
        }
        const safeMsg = message.replace(/'/g, "''");
        sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t_s},'${type}','${safeMsg}');`);
    }
});
const head = 
    'BEGIN;\n' +
    'DELETE FROM readings;\n' +
    'DELETE FROM events;\n' +
    "DELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n";
return [null, { payload: head + sql.join('\n') + '\nCOMMIT;\n' }];
return msg;
